import React, { useState } from "react";
import * as tf from "@tensorflow/tfjs";
import Session from "react-session-api";

const App = () => {
  const [activeTab, setActiveTab] = useState("registrar");

  const renderTabContent = () => {
    switch (activeTab) {
      case "registrar":
        return <div className="p-4">👋 Hello from Registrar Usuario</div>;
      case "ver":
        return <div className="p-4">📄 Hello from Ver Usuarios</div>;
      case "config":
        return <div className="p-4">⚙️ Hello from Configuración</div>;
      default:
        return null;
    }
  };

  return (
    <div className="p-4">
      <div className="flex space-x-4 mb-4">
        <button
          onClick={() => setActiveTab("registrar")}
          className={`px-4 py-2 rounded ${activeTab === "registrar" ? "bg-blue-500 text-white" : "bg-gray-200"}`}
        >
          Registrar Usuario
        </button>
        <button
          onClick={() => setActiveTab("ver")}
          className={`px-4 py-2 rounded ${activeTab === "ver" ? "bg-blue-500 text-white" : "bg-gray-200"}`}
        >
          Ver Usuarios
        </button>
        <button
          onClick={() => setActiveTab("config")}
          className={`px-4 py-2 rounded ${activeTab === "config" ? "bg-blue-500 text-white" : "bg-gray-200"}`}
        >
          Configuración
        </button>
      </div>

      <div className="border p-4 rounded shadow">
        {renderTabContent()}
      </div>
    </div>
  );
};

export default App;